questionvariables.text:
/* Generate Pythagorean triple variables to ensure integer results */
m : 2 + rand(8);
n : 1 + rand(m-1);

/* Half diagonals and side */
a : m^2 - n^2; 
b : 2*m*n ;  
c : m^2 + n^2; 

/* Final Variables */
d1 : a * 2; 
d2 : b * 2;
Area : (d1 * d2) / 2;
side : c;

/* Teacher Answer */
ta : side;

/* Mistakes for PRT */
m1 : c * 4;                 /* Found perimeter instead of side length */
m2 : d2;                    /* Found the missing diagonal and stopped early */
m3 : float(sqrt(d1^2 + d2^2)); /* Used full diagonals in Pythagoras instead of halves */
